Section CANSEC1. Context {rc : runConstT}.
Section AX2G.
  Variable AI : AMallocIface.
  Notation CI := (aci AI).
  Variables (L : alayout) (RNG : footprint) (st : astate) (LB : list ablock).
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (FR : bvmap 5 word) (fc : bv 32) (m0 : amem).
  Variables (DST dcap SS DT mtl tl lo : Z) (src : list Z) (cells : list deltX2) (cbs : list byte) (pdt : aptr) (SBL SBH : Z).
  Notation SP := (bv_unsigned sp).
  Notation SPF := (SP + -64).
  Notation n := (zlen src).
  Notation DTL := (DTABLE_BYTES mtl).
  Hypothesis AH : AHEAP AI L RNG st LB m0.
  Hypothesis HDT : In (HB pdt DT DTL) LB.
  Hypothesis HOUT : (DST = 0 /\ dcap = 0) \/ (exists pb, In (HB pb DST dcap) LB).
  Hypothesis LOA : ATOP + 4096 <= lo.
  Hypothesis LOS : lo <= SP - HUF_DEC_STACK_A.
  Hypothesis SPT : SP + 16 < al_top L.
  Hypothesis SP16 : SP mod 16 = 0.
  (* [comment removed for export] *)
  Hypothesis TOK : x2_table_ok cells tl.
  Hypothesis ECB : cbs = firstn (Z.to_nat (4 * 2^tl)) (x2_bytes' cells).
  Hypothesis LCB : zlen cbs = 4 * 2^tl.
  Hypothesis MTL : 1 <= mtl <= 12.
  Hypothesis TLM : tl <= mtl.
  (* [comment removed for export] *)
  Hypothesis DC : 0 <= dcap < 2^32.
  Hypothesis NSM : 1 <= n < 2^26.
  Hypothesis S16 : 16 <= SS.
  Hypothesis SBB : SBL <= SS /\ SS + n <= SBH.
  Hypothesis SBA : ablk SBL SBH /\ SBL mod 8 = 0.
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  (* [comment removed for export] *)
  Hypothesis DJ1 : KXGoM.apart DST dcap DT DTL.
  Hypothesis DJ2 : KXGoM.apart DST dcap SS n.
  Hypothesis DJ3 : KXGoM.apart SS n DT DTL.
  (* [comment removed for export] *)
  Hypothesis UDT : unpoisoned m0 DT (DT + DTL).
  Hypothesis UDB : unpoisoned m0 DST (DST + dcap).
  Hypothesis USB : unpoisoned m0 SBL SBH.
  Hypothesis WSK : rng RNG lo (al_top L - lo).
  Hypothesis WIM : rng_aimg RNG.
  Hypothesis WDT : rng RNG DT DTL.
  Hypothesis WSB : rng RNG SBL (SBH - SBL).
  Hypothesis WDTS : rng RNG (shad DT) (shlen (DTL + 7)).
  Hypothesis WSBS : rng RNG (shad SBL) (shlen (SBH - SBL + 7)).
  Hypothesis WDB : 0 < dcap -> rng RNG DST dcap.
  Hypothesis WDBS : 0 < dcap -> rng RNG (shad DST) (shlen (dcap + 7)).

  Notation DW := [(SP + -56, SP); (DST, DST + dcap)].
  Notation POST := (huf_dec_postA AI L RNG ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc st LB DST dcap lo m0).
  Notation FRS6 := [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

  Notation A2 l := (l AI L RNG st LB ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc m0 DST dcap SS DT mtl tl lo src cells cbs
                      pdt SBL SBH AH HDT HOUT LOA LOS SPT SP16 TOK ECB LCB MTL TLM DC NSM S16 SBB SBA BYS DJ1 DJ2 DJ3 UDT UDB USB
                      WSK WIM WDT WSB WDTS WSBS WDB WDBS) (only parsing).
  Notation AX2M' mm := (AX2M ra sp s0 s1 s2 s3 s4 s5 m0 DST dcap SS DT lo src cbs mm).

  Ltac dec_ifF := lazymatch goal with |- evtF _ _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
    let b := eval vm_compute in c in change c with b; cbv iota end.

  (* [comment removed for export] *)
  Ltac ax2_dec_facts mm MU :=
    pose proof (A2 ax2_unp mm MU) as (UDT' & UDB' & USB');
    pose proof (A2 ax2_blocks) as (B1 & B2 & B3 & B4 & B5 & B6); destruct (B6 ltac:(lia)) as (Q1 & Q2 & Q3 & Q4');
    pose proof (A2 ax2_sp_bounds) as SB; pose proof (A2 ax2_outb) as OB;
    pose proof (WDB ltac:(lia)) as WDB'; pose proof (WDBS ltac:(lia)) as WDBS';
    pose proof TOK as (TL & TC & TCK); unfold HUF_TABLELOG_MAX in TL; unfold FseNCount.Zlength in TC;
    assert (P2 : 2 <= 2 ^ tl <= 4096) by (split; [change 2 with (2^1) at 1 | change 4096 with (2^12)]; apply Z.pow_le_mono_r; lia);
    assert (DTLb : DT + 4 + 4 * 2^tl <= DT + DTABLE_BYTES mtl)
      by (unfold DTABLE_BYTES, HufHarness.DT_BYTES; assert (2^tl <= 2^mtl) by (apply Z.pow_le_mono_r; lia); lia);
    assert (LCBn : Z.of_nat (length cbs) = 4 * 2 ^ tl) by exact LCB;
    assert (LSM : Z.of_nat (length (map (Z_to_bv 8) src)) = n) by (rewrite length_map; reflexivity);
    assert (DSH : KXGoM.apart DST dcap 0x7fff8000 17592186044416) by (unfold KXGoM.apart, AIMG_HI, KLS in *; lia);
    pose proof (bv_unsigned_in_range 64 sp) as RSP; unfold bv_modulus in RSP; cbn in RSP;
    pose proof ATOP_range as ATR; unfold ATOP_MIN, ATOP_MAX in ATR;
    unfold AIMG_HI, KLS in *.

  (* [comment removed for export] *)
  Ltac ax2_post q W buf :=
    kx_post_regs_keep;
    lazymatch goal with H : u8arr asegs ?mm DST _, HL : log_flat _ _ |- _ =>
      let buf' := fresh "buf'" in let OUT' := fresh "OUT'" in let LB' := fresh "LB'" in
      destruct (kx_u8arr_ex asegs _ mm _ DST buf H HL) as (buf' & OUT' & LB') end;
    lazymatch goal with H : munch [(?a, ?b); (DST, ?c)] m0 ?mm |- _ =>
      let MUW := fresh "MUW" in let WMr := fresh "WMr" in
      pose proof (munch_refl [(DST + q, DST + q + W)] mm) as MUW; pose proof (wmono_refl asegs mm) as WMr;
      kx_munch_wins MUW [(DST + q, W)]; kx_munch_wins H [(DST + q, W)] end;
    kx_post_mem_free;
    lazymatch goal with |- context [mem_denot ?E ?mm ?l] => let EM1 := fresh "EM1" in remember (mem_denot E mm l) as m1 eqn:EM1 end;
    lazymatch goal with H : u8arr asegs ?mm DST (map _ buf) |- _ => clear H end;
    unfold KXGoM.apart in DJ1, DJ2, DJ3;
    lazymatch goal with MUW' : munch [(DST + q, DST + q + W)] ?mm ?m1', WMr' : wmono asegs ?mm ?m1' |- _ =>
      transport_after_call asegs mm m1' MUW' WMr' end;
    lazymatch goal with OUT' : u8arr asegs ?m1' DST (map _ ?b'), LB' : length ?b' = length buf |- _ =>
      assert (XM' : AX2M' m1')
        by (split; [exists b'; split; [exact OUT'| unfold zlen in *; rewrite LB'; assumption]|];
            repeat (split; [first [eassumption | eexists; eassumption]|]); first [eassumption | eexists; eassumption]) end.

  (* [comment removed for export] *)
  Ltac ax2_postP P W buf :=
    kx_post_regs_keep;
    lazymatch goal with H : u8arr asegs ?mm DST _, HL : log_flat _ _ |- _ =>
      let buf' := fresh "buf'" in let OUT' := fresh "OUT'" in let LB' := fresh "LB'" in
      destruct (kx_u8arr_ex asegs _ mm _ DST buf H HL) as (buf' & OUT' & LB') end;
    lazymatch goal with H : munch [(?a, ?b); (DST, ?c)] m0 ?mm |- _ =>
      let MUW := fresh "MUW" in let WMr := fresh "WMr" in
      pose proof (munch_refl [(P, P + W)] mm) as MUW; pose proof (wmono_refl asegs mm) as WMr;
      kx_munch_wins MUW [(P, W)]; kx_munch_wins H [(P, W)] end;
    kx_post_mem_free;
    lazymatch goal with |- context [mem_denot ?E ?mm ?l] => let EM1 := fresh "EM1" in remember (mem_denot E mm l) as m1 eqn:EM1 end;
    lazymatch goal with H : u8arr asegs ?mm DST (map _ buf) |- _ => clear H end;
    unfold KXGoM.apart in DJ1, DJ2, DJ3;
    lazymatch goal with MUW' : munch [(P, P + W)] ?mm ?m1', WMr' : wmono asegs ?mm ?m1' |- _ =>
      transport_after_call asegs mm m1' MUW' WMr' end;
    lazymatch goal with OUT' : u8arr asegs ?m1' DST (map _ ?b'), LB' : length ?b' = length buf |- _ =>
      assert (XM' : AX2M' m1')
        by (split; [exists b'; split; [exact OUT'| unfold zlen in *; rewrite LB'; assumption]|];
            repeat (split; [first [eassumption | eexists; eassumption]|]); first [eassumption | eexists; eassumption]) end.

  (* [comment removed for export] *)
  Ltac ax2_tab_run stop v :=
    kx_runFL [stop] 40%nat
      [KZIdx tl (2^tl); KZRange (64 - tl) 52 63;
       KZRange v 0 4095; KZRange (2^tl - v - 1) 0 4095; KZRange (2^tl) 2 4096; KZRange tl 1 12;
       KZTab (DT + 4) (4 * 2^tl) 4 [(2, 0, 12); (3, 1, 2)];
       KZRange DT 0x5ed000 (2^47 - 8388608)]
      [(DT + 4, 4 * 2^tl)]
      [(DT + 4, 4 * 2^tl)]
      [(DT + 4, 4 * 2^tl)];
    try (lazymatch goal with |- evtF _ _ _ _ => fail | _ => unfold KXGoM.apart in *; lia end);
    kx_post_regs_keep;
    lazymatch goal with |- context [mem_denot ?E ?mm []] => change (mem_denot E mm []) with mm end.

  (* [comment removed for export] *)



  Ltac brute_regZ n r lo cnt g :=
    let w := getreg n in
    lazymatch w with
    | Z_to_bv 64 ?e =>
        let F := eval pattern r in e in
        lazymatch F with
        | ?f r =>
            let H := fresh "BR" in
            assert (H : forall r0, lo <= r0 < lo + cnt -> (f r0 =? g r0) = true)
              by (apply (brute_range (fun r0 => f r0 =? g r0) lo cnt); vm_compute; reflexivity);
            replace e with (g r) by (symmetry; apply Z.eqb_eq; apply H; lia);
            clear H
        end
    | _ => fail "brute_regZ: register" n "holds" w
    end.

  (* [comment removed for export] *)
  Lemma ax2_sjoin : forall r mm (c t0 t1 x8 x9 a6 x18 x19 x20 x21 t3 t4 t5 t6 xra : word),
    1 <= r <= 255 -> n <= 7 -> AX2M' mm ->
    bytes_at asegs mm DT [Z_to_bv 8 mtl; Z_to_bv 8 1; Z_to_bv 8 tl; Z_to_bv 8 mtl] ->
    evtF asegs RNG POST (MS (mkR xra (Z_to_bv 64 SPF) gp tp t0 t1 c x8 x9
             (Z_to_bv 64 DST) (Z_to_bv 64 dcap) (Z_to_bv 64 SS) (Z_to_bv 64 n) (Z_to_bv 64 DT) (Z_to_bv 64 r) a6
             (Z_to_bv 64 2147450880) x18 x19 x20 x21 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
