  Ltac ax2_small_post :=
    kx_post_regs_keep;
    lazymatch goal with |- context [mem_denot ?E ?mm []] => change (mem_denot E mm []) with mm end;
    lazymatch goal with |- evtF _ _ _ (MS (mkR _ _ _ _ _ _ _ _ _ _ _ _ _ _ (ev ?E ?j) _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _) _ _ _ _ _ _) =>
      let R := fresh "R" in kx_range (EVar j) R;
      replace (ev E j) with (Z_to_bv 64 (bv_unsigned (ev E j))) by (apply Z_to_bv_bv_unsigned);
      let r := fresh "r" in set (r := bv_unsigned (ev E j)) in *; clearbody r end;
    let w := getreg 7%Z in let c := fresh "c" in let Ec := fresh "Ec" in remember w as c eqn:Ec; clear Ec;
    let w := getreg 16%Z in let y := fresh "y" in let Ey := fresh "Ey" in remember w as y eqn:Ey; clear Ey;
    lazymatch goal with H : log_flat _ _ |- _ => clear H end;
    zstep;
    let K := fresh "K" in if_cases K; zify_cond K;
    [ zstep; zstep; eapply (A2 ax2_epi); eassumption
    | eapply ax2_sjoin; [lia| lia| eassumption| eassumption] ].

  (* [comment removed for export] *)
  Lemma ax2_small : forall mm (t0 t1 t2 x8 x9 a5 a6 x18 x19 x20 x21 t3 t4 t5 t6 xra : word),
    n < 8 -> AX2M' mm -> bytes_at asegs mm DT [Z_to_bv 8 mtl; Z_to_bv 8 1; Z_to_bv 8 tl; Z_to_bv 8 mtl] ->
    evtF asegs RNG POST (MS (mkR xra (Z_to_bv 64 SPF) gp tp t0 t1 t2 x8 x9
             (Z_to_bv 64 DST) (Z_to_bv 64 dcap) (Z_to_bv 64 SS) (Z_to_bv 64 n) (Z_to_bv 64 DT) a5 a6
             (Z_to_bv 64 2147450880) x18 x19 x20 x21 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
